content:
Below is a simple, practical way to implement the "toggle" behavior you described on Linux in C:

- When the program starts it looks for other running processes whose executable path matches its own (/proc/<pid>/exe).
- If no other instances are found the program continues running normally.
- If one or more other instances are found the program sends them SIGTERM, waits a short period and then escalates to SIGKILL if they do not exit, and then the newly-started instance exits as well.

Notes / caveats up front:
- The process sending signals must have permission to signal the other processes (same UID or root).
- There are race conditions that are hard to avoid completely if you must be atomic across forks/starts. A file lock (pidfile + fcntl/flock) can help for atomic detection if needed.
- Killing processes abruptly can cause data loss; use SIGTERM first to allow cleanup, then SIGKILL if necessary.

Example C program (gcc-ready):


#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <dirent.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <signal.h>
#include <errno.h>
#include <limits.h>
#include <ctype.h>
#include <time.h>
#include <stdint.h>

int is_digits(const char *s) {
    if (!s || !*s) return 0;
    for (; *s; ++s) if (!isdigit((unsigned char)*s)) return 0;
    return 1;
}

int main(void) {
    char myexe[PATH_MAX];
    ssize_t n = readlink("/proc/self/exe", myexe, sizeof(myexe) - 1);
    if (n <= 0) {
        perror("readlink(/proc/self/exe)");
        return 1;
    }
    myexe[n] = '\0';

    pid_t self = getpid();
    DIR *proc = opendir("/proc");
    if (!proc) {
        perror("opendir(/proc)");
        return 1;
    }

    pid_t matched[1024];
    size_t matched_count = 0;
    struct dirent *de;
    while ((de = readdir(proc)) != NULL) {
        if (!is_digits(de->d_name)) continue;
        pid_t pid = (pid_t)atoi(de->d_name);
        if (pid == self) continue;

        char exepath[PATH_MAX];
        char linkpath[PATH_MAX];
        snprintf(linkpath, sizeof(linkpath), "/proc/%s/exe", de->d_name);
        ssize_t r = readlink(linkpath, exepath, sizeof(exepath) - 1);
        if (r <= 0) continue;
        exepath[r] = '\0';

        if (strcmp(exepath, myexe) == 0) {
            if (matched_count < sizeof(matched)/sizeof(matched[0])) {
                matched[matched_count++] = pid;
            }
        }
    }
    closedir(proc);

    if (matched_count == 0) {
        printf("No other instance found — continuing.\n");
        /* Normal program work goes here. Example loop to keep process alive: */
        for (;;) {
            pause(); /* or sleep / do real work */
        }
    } else {
        printf("Found %zu other instance(s). Terminating them.\n", matched_count);

        /* Send SIGTERM politely first */
        for (size_t i = 0; i < matched_count; ++i) {
            if (kill(matched[i], SIGTERM) == -1) {
                if (errno != ESRCH) perror("kill(SIGTERM)");
            }
        }

        /* Wait up to timeout for each pid to disappear; escalate to SIGKILL if still alive */
        const int timeout_seconds = 5;
        for (size_t i = 0; i < matched_count; ++i) {
            int alive = 1;
            for (int t = 0; t < timeout_seconds * 10; ++t) { /* check every 100ms */
                if (kill(matched[i], 0) == -1) {
                    if (errno == ESRCH) { alive = 0; break; }
                }
                usleep(100000);
            }
            if (alive) {
                if (kill(matched[i], SIGKILL) == -1) {
                    if (errno != ESRCH) perror("kill(SIGKILL)");
                }
            }
        }

        printf("Exiting this instance as part of toggle.\n");
        /* exit this (new) instance as well */
        return 0;
    }
}


Build:
gcc -O2 -Wall -o toggle toggle.c

Behavior example:
- Start ./toggle — it finds no other instance and continues running.
- Start ./toggle again — the second process finds existing instance(s), sends them SIGTERM (then SIGKILL if needed), and then the second process exits. End result: both existing and new are terminated (i.e., there are no running copies).

Alternative / improvements:
- Use a pidfile + fcntl() advisory lock for atomic detection of another holder. The lock-holder can write its PID so a latecomer can read it and kill that PID. That avoids /proc scanning but requires cooperating processes to use the same pidfile lock scheme.
- Use a Unix domain socket bound to a fixed path: try to bind(); if bind fails because address in use, connect to the socket and send a shutdown request / signal—this requires a server in the running instance.
- Consider adding signal handlers in your program to perform cleanup on SIGTERM before exiting.

If you want, I can:
- provide a pidfile + fcntl-based toggle implementation, or
- add a small signal handler so the instance can clean up before dying, or
- make the /proc scanner also include matching by argv[0] / cmdline if you prefer.
